/** Protects sibling VALUES semantics around a scope-marked positive UNION. */
class LmdbNativeScopedUnionValuesTest {
	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI FOCUS = iri("urn:scope:focus");
	private static final IRI OTHER_FOCUS = iri("urn:scope:other-focus");
	private static final IRI LINK = iri("urn:scope:link");
	private static final IRI ALTERNATE = iri("urn:scope:alternate");
	private static final IRI OTHER_ONE = iri("urn:scope:other-one");
	private static final IRI OTHER_TWO = iri("urn:scope:other-two");
	private static final IRI VALUE_ONE = iri("urn:scope:value-one");
	private static final IRI VALUE_TWO = iri("urn:scope:value-two");
	private static final IRI VALUE_THREE = iri("urn:scope:value-three");
	private static final IRI VALUE_FOUR = iri("urn:scope:value-four");
	private static final Value TAG = VF.createLiteral("duplicate");
	private static final String QUERY = "SELECT ?focus ?value ?focusBoundInUnion ?focusBoundAfterValues ?tag WHERE { "
			+ "{ "
			+ "{ ?focus <urn:scope:link> ?value . BIND(BOUND(?focus) AS ?focusBoundInUnion) } "
			+ "UNION "
			+ "{ { ?other <urn:scope:link> ?value . } UNION { ?other <urn:scope:alternate> ?value . } "
			+ "BIND(BOUND(?focus) AS ?focusBoundInUnion) } "
			+ "} "
			+ "VALUES (?focus ?tag) { (<urn:scope:focus> \"duplicate\") "
			+ "(<urn:scope:focus> UNDEF) (<urn:scope:focus> \"duplicate\") } "
			+ "BIND(BOUND(?focus) AS ?focusBoundAfterValues) "
			+ "}";
	private static final Pattern NATIVE_INVOCATIONS = Pattern.compile("nativeInvocationsActual=(\\d+)");

	@TempDir
	Path directory;

	@ParameterizedTest(name = "uniform VALUES preserves nested scope-marked UNION behavior; adjacency={0}")
	@ValueSource(booleans = { false, true })
	void uniformValuesSiblingPreservesScopedUnionBranches(boolean adjacency) throws Exception {
		assertParsedScopeBoundary();

		LmdbStore nativeStore = new LmdbStore(directory.resolve("native-" + adjacency).toFile(),
				new LmdbStoreConfig().setNativeEvaluationEnabled(true).setDirectAdjacencyEnabled(adjacency));
		LmdbStore genericStore = new LmdbStore(directory.resolve("generic-" + adjacency).toFile(),
				new LmdbStoreConfig().setNativeEvaluationEnabled(false).setDirectAdjacencyEnabled(false));
		SailRepository nativeRepository = new SailRepository(nativeStore);
		SailRepository genericRepository = new SailRepository(genericStore);
		nativeRepository.init();
		genericRepository.init();
		try {
			load(nativeRepository);
			load(genericRepository);
			assertThat(nativeStore.getLmdbStats().tripleDatabases().keySet())
					.as("the scope control uses the default spoc,posc index pair")
					.contains("spocspoc", "poscposc")
					.doesNotContain("ospcospc");
			if (adjacency) {
				assertThat(nativeStore.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS))
						.as(nativeStore.getDirectAdjacencyReadinessDescription())
						.isTrue();
			}

			try (var nativeConnection = nativeRepository.getConnection();
					var genericConnection = genericRepository.getConnection()) {
				assertQuery(nativeConnection, genericConnection, adjacency, "no incoming focus", Map.of(),
						expectedRows(false));
				assertQuery(nativeConnection, genericConnection, adjacency, "matching incoming focus",
						Map.of("focus", FOCUS), expectedRows(true));
				assertQuery(nativeConnection, genericConnection, adjacency,
						"nonmatching input prunes the focus arm; VALUES owns output focus",
						Map.of("focus", OTHER_FOCUS),
						expectedRowsForNonmatchingInput());
			}
		} finally {
			nativeRepository.shutDown();
			genericRepository.shutDown();
		}
	}

	private static void assertParsedScopeBoundary() throws Exception {
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr();
		String shape = describeAlgebraShape(parsed);
		Path shapeArtifacts = Files.createDirectories(Path.of("target", "scoped-union-values-control", "parse-shape"));
		Files.writeString(shapeArtifacts.resolve("parsed-algebra.txt"), parsed.toString());
		Files.writeString(shapeArtifacts.resolve("boundary-summary.txt"), shape);
		boolean[] mandatorySiblingJoin = { false };
		boolean[] scopedUnionWithUnboundArm = { false };
		int[] unionCount = { 0 };
		parsed.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Join join) {
				if ((containsUniformFocusValues(join.getLeftArg())
						&& containsScopeMarkedUnionWithUnboundArm(join.getRightArg()))
						|| (containsUniformFocusValues(join.getRightArg())
								&& containsScopeMarkedUnionWithUnboundArm(join.getLeftArg()))) {
					mandatorySiblingJoin[0] = true;
				}
				super.meet(join);
			}

			@Override
			public void meet(Union union) {
				unionCount[0]++;
				super.meet(union);
			}
		});
		parsed.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Union union) {
				if (containsScopeMarkedUnionWithUnboundArm(union)) {
					scopedUnionWithUnboundArm[0] = true;
				}
				super.meet(union);
			}
		});
		assertThat(unionCount[0]).as("the control contains an outer UNION and nested UNION arms")
				.isGreaterThanOrEqualTo(2);
		assertThat(scopedUnionWithUnboundArm[0])
				.as("a scope-marked positive UNION arm exports focus while its sibling does not")
				.isTrue();
		assertThat(mandatorySiblingJoin[0])
				.as("the scope-marked UNION and fixed-focus VALUES table are mandatory Join siblings\n%s", shape)
				.isTrue();
	}

	private static String describeAlgebraShape(TupleExpr expression) {
		StringBuilder shape = new StringBuilder();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Join join) {
				shape.append("Join scope=")
						.append(TupleExprs.isVariableScopeChange(join))
						.append(" left=")
						.append(join.getLeftArg().getClass().getSimpleName())
						.append(" leftValues=")
						.append(containsUniformFocusValues(join.getLeftArg()))
						.append(" leftScopedUnion=")
						.append(containsScopeMarkedUnionWithUnboundArm(join.getLeftArg()))
						.append(" right=")
						.append(join.getRightArg().getClass().getSimpleName())
						.append(" rightValues=")
						.append(containsUniformFocusValues(join.getRightArg()))
						.append(" rightScopedUnion=")
						.append(containsScopeMarkedUnionWithUnboundArm(join.getRightArg()))
						.append('\n');
				super.meet(join);
			}

			@Override
			public void meet(Union union) {
				shape.append("Union scope=")
						.append(TupleExprs.isVariableScopeChange(union))
						.append(" leftBindings=")
						.append(union.getLeftArg().getBindingNames())
						.append(" rightBindings=")
						.append(union.getRightArg().getBindingNames())
						.append('\n');
				super.meet(union);
			}

			@Override
			public void meet(BindingSetAssignment assignment) {
				shape.append("VALUES names=")
						.append(assignment.getBindingNames())
						.append(" rowCount=")
						.append(count(assignment.getBindingSets()))
						.append(" scope=")
						.append(TupleExprs.isVariableScopeChange(assignment))
						.append('\n');
				super.meet(assignment);
			}
		});
		return shape.toString();
	}

	private static int count(Iterable<?> items) {
		int result = 0;
		for (Object ignored : items) {
			result++;
		}
		return result;
	}

	private static boolean containsUniformFocusValues(TupleExpr expression) {
		boolean[] found = { false };
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment assignment) {
				Value fixed = null;
				boolean uniform = assignment.getBindingSets().iterator().hasNext();
				for (BindingSet row : assignment.getBindingSets()) {
					Value value = row.getValue("focus");
					if (value == null || (fixed != null && !fixed.equals(value))) {
						uniform = false;
						break;
					}
					fixed = value;
				}
				found[0] |= uniform;
				super.meet(assignment);
			}
		});
		return found[0];
	}

	private static boolean containsScopeMarkedUnionWithUnboundArm(TupleExpr expression) {
		boolean[] found = { false };
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Union union) {
				boolean leftFocus = union.getLeftArg().getBindingNames().contains("focus");
				boolean rightFocus = union.getRightArg().getBindingNames().contains("focus");
				if (TupleExprs.isVariableScopeChange(union) && leftFocus != rightFocus) {
					found[0] = true;
				}
				super.meet(union);
			}
		});
		return found[0];
	}

	private static void assertQuery(org.eclipse.rdf4j.repository.sail.SailRepositoryConnection nativeConnection,
			org.eclipse.rdf4j.repository.sail.SailRepositoryConnection genericConnection, boolean adjacency,
			String label, Map<String, Value> bindings, List<BindingSet> expected) throws Exception {
		TupleQuery genericQuery = genericConnection.prepareTupleQuery(QUERY);
		((SailQuery) genericQuery).setLmdbResultCacheRequested(false);
		bindings.forEach(genericQuery::setBinding);
		List<BindingSet> genericRows = evaluate(genericQuery);
		assertThat(bag(genericRows))
				.as("independent expected bag for the generic scope control: %s", label)
				.containsExactlyInAnyOrderEntriesOf(bag(expected));

		TupleQuery nativeQuery = nativeConnection.prepareTupleQuery(QUERY);
		((SailQuery) nativeQuery).setLmdbResultCacheRequested(false);
		bindings.forEach(nativeQuery::setBinding);
		List<BindingSet> nativeRows = evaluate(nativeQuery);
		assertThat(bag(nativeRows))
				.as("native scope control preserves the independent exact bag: %s; adjacency=%s", label, adjacency)
				.containsExactlyInAnyOrderEntriesOf(bag(expected));

		String telemetry = nativeQuery.explain(Explanation.Level.Telemetry).toString();
		assertThat(telemetry).startsWith("LMDB native physical plan (executed)");
		Matcher invocations = NATIVE_INVOCATIONS.matcher(telemetry);
		long invocationCount = 0;
		while (invocations.find()) {
			invocationCount += Long.parseLong(invocations.group(1));
		}
		if (bindings.isEmpty()) {
			assertThat(invocationCount)
					.as("the unbound-entry control executes an actual native component\n%s", telemetry)
					.isPositive();
		}

		Path artifacts = Files.createDirectories(Path.of("target", "scoped-union-values-control",
				"adjacency-" + adjacency, label.replace(' ', '-')));
		Files.writeString(artifacts.resolve("query.rq"), QUERY);
		Files.writeString(artifacts.resolve("parsed-algebra.txt"),
				QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr().toString());
		Files.writeString(artifacts.resolve("generic-bag.txt"),
				String.join(System.lineSeparator(), canonicalRows(genericRows)));
		Files.writeString(artifacts.resolve("native-bag.txt"),
				String.join(System.lineSeparator(), canonicalRows(nativeRows)));
		Files.writeString(artifacts.resolve("native-telemetry.txt"), telemetry);
	}

	private static List<BindingSet> expectedRows(boolean incomingFocus) {
		List<BindingSet> rows = new ArrayList<>();
		if (incomingFocus) {
			appendExpectedRows(rows, VALUE_ONE, true);
			appendExpectedRows(rows, VALUE_ONE, true);
			appendExpectedRows(rows, VALUE_TWO, true);
			appendExpectedRows(rows, VALUE_TWO, true);
			appendExpectedRows(rows, VALUE_THREE, true);
			appendExpectedRows(rows, VALUE_FOUR, true);
		} else {
			appendExpectedRows(rows, VALUE_ONE, true);
			appendExpectedRows(rows, VALUE_ONE, false);
			appendExpectedRows(rows, VALUE_TWO, true);
			appendExpectedRows(rows, VALUE_TWO, false);
			appendExpectedRows(rows, VALUE_THREE, false);
			appendExpectedRows(rows, VALUE_FOUR, false);
		}
		return rows;
	}

	private static List<BindingSet> expectedRowsForNonmatchingInput() {
		List<BindingSet> rows = new ArrayList<>();
		appendExpectedRows(rows, VALUE_ONE, true);
		appendExpectedRows(rows, VALUE_TWO, true);
		appendExpectedRows(rows, VALUE_THREE, true);
		appendExpectedRows(rows, VALUE_FOUR, true);
		return rows;
	}

	private static void appendExpectedRows(List<BindingSet> rows, IRI value, boolean focusBoundInUnion) {
		for (Value tag : new Value[] { TAG, null, TAG }) {
			MapBindingSet row = new MapBindingSet(5);
			row.addBinding("focus", FOCUS);
			row.addBinding("value", value);
			row.addBinding("focusBoundInUnion", VF.createLiteral(focusBoundInUnion));
			row.addBinding("focusBoundAfterValues", VF.createLiteral(true));
			if (tag != null) {
				row.addBinding("tag", tag);
			}
			rows.add(row);
		}
	}

	private static void load(SailRepository repository) {
		try (var connection = repository.getConnection()) {
			connection.begin();
			connection.add(FOCUS, LINK, VALUE_ONE);
			connection.add(FOCUS, LINK, VALUE_TWO);
			connection.add(OTHER_ONE, LINK, VALUE_THREE);
			connection.add(OTHER_TWO, ALTERNATE, VALUE_FOUR);
			connection.commit();
		}
	}

	private static List<BindingSet> evaluate(TupleQuery query) {
		List<BindingSet> rows = new ArrayList<>();
		try (var result = query.evaluate()) {
			result.forEach(rows::add);
		}
		return rows;
	}

	private static Map<BindingSet, Integer> bag(List<BindingSet> rows) {
		Map<BindingSet, Integer> bag = new HashMap<>();
		rows.forEach(row -> bag.merge(row, 1, Integer::sum));
		return bag;
	}

	private static List<String> canonicalRows(List<BindingSet> rows) {
		List<String> canonical = new ArrayList<>(rows.size());
		for (BindingSet row : rows) {
			List<String> bindings = new ArrayList<>();
			for (String name : row.getBindingNames()) {
				bindings.add(name + "=" + row.getValue(name));
			}
			bindings.sort(String::compareTo);
			canonical.add(String.join("|", bindings));
		}
		canonical.sort(String::compareTo);
		return canonical;
	}

	private static IRI iri(String value) {
		return VF.createIRI(value);
	}
}
